registerRefData('nsw-cond-n-418',{"id":418,"pan":null,"ref":"DA 16-2024-28-1","address":"38 Cabbage Tree Road Williamtown 2318","description":"High technology industrial development comprising office and workshop areas, car parking, site works and associated development","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-04-04","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-276!20250403T205429.930 GMT","sha256":"52ffdeb263f25e5768ba851dd9609deb5087c237da3d3ad388ad886ad0a965c9","pages":27,"layout":"numbered","n":91,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/418.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/high-technology-industrial-development-comprising-office-and-workshop-areas-car-parking-site-works-and-associated-development","lga":"PORT STEPHENS","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-276 - Port Stephens - DA 16 - 2024-28-1","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT High technology industrial development comprising office and workshop","text":"areas, car parking, site works and associated development","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 38 Cabbage Tree Road, Williamtown 2318 -","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Barr Property and Planning Pty Ltd","text":"Greater Newcastle Aerotropolis Pty Ltd","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Council related development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Sustainable Buildings) 2022\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021\no State Environmental Planning Policy (Industry and Employment)\n2021\no Port Stephens Local Environmental Plan 2014\n• Draft environmental planning instruments\n• Development control plans:\no Port Stephens Development Control Plan 2014\n• Planning agreements: Nil\n• Provisions of the Environmental Planning and Assessment Regulation\n2021: Section 62 (Fire Safety), Section 66A Council related\ndevelopment)\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council assessment report: 24 March 2025\n• Written submissions during public exhibition: Nil\n• Total number of unique submissions received by way of objection: Nil","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Preliminary Briefing: 5 March 2024\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony\nMcNamara\no Council assessment staff: Courtney Sargent, Ryan Falkenmire\no Applicant Representatives: Tracey Groves, Jamie Nowland, Rob\nGreen, Shane Murray, Rebecca Johnston, Samuel Liu, Amie\nMcMullen\no Department: Leanne Harris, Holly McCann\n• Site inspection:\no Panel members:\n- Alison McCabe (Chair): 31 July 2023\n- Roberta Ryan: 27 October 2024\n• Final briefing to discuss Council’s recommendation: 1 April 2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Amanda\nWetzel\no Council assessment staff: Courtney Sargent, Mattew Eagan\no Applicant representatives: Rebecca Johnston, Mark Purdy, Peter\nWych, Kathy Gresham, Guy Page and Robert Burrows\no Department: Leanne Harris, Holly McCann","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council assessment report","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"1","code":null,"number":"1","title":"Approved plans and supporting documentation","text":"Development must be carried out in accordance with the following approved plans and documents,\nexcept where the conditions of this consent expressly require otherwise.\nApproved plans\nPlan\nnumber\nRevision number Plan title Drawn by Date of\nplan\n15111\nDA-A-003\nS Site Plan EJE Architecture 20/09/2024\n15111\nDA-A-100\nN Ground Floor Plan EJE Architecture 20/09/2024\n15111\nDA-A-101\nN Level 1 Plan EJE Architecture 20/09/2024\n15111\nDA-A-102\nM Roof Plan EJE Architecture 20/09/2024\nSCHEDULE 2\n15111\nDA-A-200\nM Elevations - Sheet","stage":"general","stage_basis":"heading","page":5},{"label":"1","code":null,"number":"1","title":"EJE Architecture 20/09/2024","text":"15111\nDA-A-201\nM Elevations - Sheet","stage":"general","stage_basis":"heading","page":6},{"label":"2","code":null,"number":"2","title":"EJE Architecture 20/09/2024","text":"15111\nDA-A-300\nM Sections EJE Architecture 20/09/2024\n15111\nDA-A-201\nJ Site Perimeter\nFencing Plan\nEJE Architecture 20/09/2024\n15111\nDA-A-404\nJ Material Palette EJE Architecture 20/09/2024\n15118.5\nL010\nJ Site Plan Terras Landscape\nArchitects\n16/08/2024\n15118.5\nL011\nJ Site Analysis Terras Landscape\nArchitects\n16/08/2024\n15118.5\nL012\nI Material Palette Terras Landscape\nArchitects\n12/08/2024\nNA231561\nC02-0001\nF Overall Site Plan Acor Consultants 14/08/2024\nNA231561\nC02-0101\nF Site Grading Plan\n- Sheet 1\nAcor Consultants 14/08/2024\nNA231561\nC02-0102\nF Site Grading Plan\n- Sheet 2\nAcor Consultants 14/08/2024\nNA231561\nC03-0001\nF Soil Erosion and\nSediment Control\nPlan - Sheet 1\nAcor Consultants 14/08/2024\nNA231561\nC03-0101\nF Soil Erosion and\nSediment Control\nPlan - Sheet 1\nAcor Consultants 14/08/2024\nNA231561\nC08-0001\nF Stormwater\nManagement Plan\nAcor Consultants 14/08/2024\nApproved Documents\nDocument title Version\nNo.\nPrepared by Dated\nCivil Engineering Report Development\nApplication\nG Acor Consultants\nPty Ltd\n16/08/2024\nReference: NA231561_ R01_Civil\nEngineering DA Report.docx\nAcoustic Assessment for DA\nReference: TN679-01F02","stage":"general","stage_basis":"heading","page":6},{"label":"4","code":null,"number":"4","title":"Renzo Tonin &","text":"Associates\n27/02/2024\nOperational Waste Management Plan D Elephants Foot\nConsulting\n28/02/2024\nConstruction Waste Management Plan C Elephants Foot\nConsulting\n28/02/2024\nRemediation Action Plan\nReference: NEW24P-0090-AG","stage":"general","stage_basis":"heading","page":7},{"label":"1","code":null,"number":"1","title":"Qualtest","text":"Laboratory (NSW)\nPty Ltd\n21/05/2024\nAccess Report\nReference: PAA_23489","stage":"general","stage_basis":"heading","page":7},{"label":"3","code":null,"number":"3","title":"Lindsay Perry","text":"Access Pty Ltd\n26/02/2024\nSustainable Building SEPP Net Zero\nStatement\nProject No. MN14719\n3 Marline Newcastle\nPty Ltd\n24/01/2024\nIn the event of any inconsistency with the approved plans and a condition of this consent, the\ncondition prevails.\n2. Transport for NSW, Reference: NTH24/00160/001, dated 28 February 2024.\n3. Department of Defence, Reference: ID-EP-DLP&R/OUT/2025/ BS64583972, dated 26\nFebruary 2025.\n4. Ausgrid, Reference:1900126830, dated 19 February 2024.\n3 Building Code of Australia\nAll building work must be carried out in accordance with the BCA. In this clause, a reference to the\nBCA is a reference to that Code as in force on the date the application for the relevant Construction\nCertificate is made.","stage":"general","stage_basis":"heading","page":7},{"label":"4","code":null,"number":"4","title":"Sign on Building","text":"Except in the case of work only carried out to the interior of a building or Crown building work, a sign\nmust be erected in a prominent position on the site showing the name, address and telephone\nnumber of the Principal Certifying Authority for the work, the name of any principal contractor and\ntheir after-hours contact number, and must contain a statement that unauthorised entry to the site\nis prohibited.\nThe sign must be maintained while the work is being carried out and is to be removed when the\nwork is completed.","stage":"general","stage_basis":"heading","page":7},{"label":"5","code":null,"number":"5","title":"Signage Approvals","text":"A separate development application for any proposed signs in addition to those signs approved as\npart of this development consent, must be provided to, and approved by, the Consent Authority or\nunder the provisions of the State Environmental Planning Policy (Exempt and Complying Codes) 2008\nif applicable prior to the erection or display of any such signs.\nNo consent is given or implied for any form of illumination or floodlighting to any sign.","stage":"general","stage_basis":"heading","page":8},{"label":"6","code":null,"number":"6","title":"Building Materials","text":"Building materials used for construction are to be non-reflective. If it is later found that glare\nendangers the safety of aircraft operations, the Department of Defence may require material and\ndesign modifications at full cost to the proponent.","stage":"general","stage_basis":"heading","page":8},{"label":"7","code":null,"number":"7","title":"Sustainable Buildings - Large Commercial Development","text":"The development must be undertaken in accordance with the NABERS commitment agreement\n(Agreement No. AR00016, Dated 17 June 2024).","stage":"general","stage_basis":"heading","page":8},{"label":"8","code":null,"number":"8","title":"Validation Report","text":"Prior to issue of a Construction Certificate, a Validation Report prepared by a suitability qualified\nperson must be provided to the Certifying Authority and Council within 30 days following completion\nof the remediation works, which demonstrates:\na) Compliance with the approved Remediation Action Plan (RAP);\nb) that the remediation acceptance criteria (in the approved RAP) has been fully complied with;\nc) that all remediation works undertaken comply with the Contaminated Lands Planning\nGuidelines, Contaminated Lands Management Act 1997, Chapter 4 of State Environmental\nPlanning Policy (Resilience and Hazards) 2021 and Council’s Management of Contaminated\nLands Policy;\nand includes:\na) Works As Executed Plan(s) that identify the extent of the remediation works undertaken\n(that includes any encapsulation work) prepared by a Registered Surveyor;\nb) a “notice of completion of remediation work” as required under Clause 4.15 of he Resilience\nand Hazards SEPP; and\nc) a statement confirming that the site following remediation of contamination is suitable for\nthe intended use","stage":"before_cc","stage_basis":"heading","page":8},{"label":"9","code":null,"number":"9","title":"Erosion and sediment controls plan","text":"Before the issue of a Construction Certificate, an erosion and sediment control plan must be\nprepared by a suitably qualified person in accordance with the following documents and provided to\nthe certifier:\n1. Council’s relevant development control plan,\n2. the guidelines set out in 'Managing Urban Stormwater: Soils and Construction’ prepared by\nLandcom (the Blue Book) (as amended from time to time), and\n3. The ‘Do it Right On-Site, Soil and Water Management for the Construction Industry'\n(Southern Sydney Regional Organisation of Councils and the Natural Heritage Trust) (as\namended from time to time).","stage":"before_cc","stage_basis":"heading","page":9},{"label":"10","code":null,"number":"10","title":"Waste Management Plan requirements","text":"Before the issue of a Construction Certificate, a waste management plan for the development must\nbe prepared and provided to the certifier. The plan must be prepared:\na. in accordance with\ni. the Environment Protection Authority’s Waste Classification Guidelines as in force\nfrom time to time; and\nii. a development control plan that provides for waste management that applies to the\nland on which the work or the clearing of vegetation is carried out; and\nb. include the following information-\ni. the contact details of the person removing waste;\nii. an estimate of the type and quantity of waste;\niii. whether waste is expected to be reused, recycled or sent to landfill;\niv. the address of the disposal location for waste.\nA copy of the waste management plan must be kept on-site at all times while work approved under\nthe development consent is being carried out.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"11","code":null,"number":"11","title":"Section 7.12 development contributions","text":"A monetary contribution is to be paid to Council, pursuant to Section 7.12 of the Environmental\nPlanning & Assessment Act 1979 and the Port Stephens Local Infrastructure Contribution Plan 2020.\nThe total amount payable will be adjusted at the time payment is made, in accordance with the\nprovisions of that Plan.\nSection 7.12 contributions will be calculated with reference to the capital investment value (CIV) of\nthe development, determined in accordance with Clause 25J of the Environmental Planning and\nAssessment Regulation 2021, and the levies specified in the Port Stephens Local Infrastructure\nContributions Plan 2020as outlined below:\nCapital Investment Value Levy Rate (% of CIV)\nUp to and including $100,000 Nil\nMore than $100,000 and up to and including\n$200,000\n0.5%\nMore than $200,000 1%\nThe payment of the Fixed Local Infrastructure Contribution levy, is to be accompanied by a Cost\nSummary Report Form setting out an estimate of the CIV in accordance with Schedule 1 of the Port\nStephens Local Infrastructure Contributions Plan. A copy of the Plan and Cost Summary Report Forms\nare available Council’s website at https://www.portstephens.nsw.gov.au/, alternatively contact\nCouncil on 02 9228 055.\nWhere the estimated cost of carrying out on the whole of the development is more than $1,000,000,\nthe Cost Summary Report Form must be completed by a Quantity Surveyor who is a Registered\nAssociate member or above, of the Australia Institute of Quantity Surveyors.\nThis condition cannot be taken to be satisfied until a payment has been made in accordance with the\nCIV stated on a cost summary report submitted to Council in accordance with this condition.\nPayment of the above amount must apply to Development Applications as follows:\na) Building work only - prior to issue of the Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"12","code":null,"number":"12","title":"Long Service Levy","text":"Before the issue of a Construction Certificate, the long service levy must be paid to the Long Service\nCorporation under the Building and Construction industry Long Service Payments Act 1986, section\n34, and evidence of the payment is to be provided to the principal certifier","stage":"before_cc","stage_basis":"heading","page":10},{"label":"13","code":null,"number":"13","title":"Roads Act Approval","text":"Prior to issue of a Construction Certificate, for construction/reconstruction of Council infrastructure,\nincluding vehicular crossings, footpath, kerb and gutter, stormwater drainage, an application must be\nmade for a Roadworks Permit under Section 138B of the Roads Act 1993.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"14","code":null,"number":"14","title":"Stormwater/Drainage Plans","text":"Detailed stormwater drainage plans must be prepared by a qualified Engineer in accordance with the\napproved plans, Council’s Infrastructure Specifications and the current Australian Rainfall and Runoff\nguidelines using the Hydrologic Soil Mapping data for Port Stephens (available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of works\nwithin an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"15","code":null,"number":"15","title":"Civil engineering plans","text":"Civil engineering plans prepared by a qualified Engineer, indicating drainage, roads, access ways,\nearthworks, pavement design, street lighting, details of line-marking, traffic management, water\nquality and quantity facilities including stormwater detention and disposal, must be prepared in\naccordance with the approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.\nNote. Under the Roads Act 1993, only the Roads Authority can approve commencement of works\nwithin an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"16","code":null,"number":"16","title":"Construction Site Management Plan","text":"Before the issue of a Construction Certificate, a construction site management plan must be\nprepared, and provided to the principal certifier. The plan must include the following matters:\na. The location and materials for protective fencing and hoardings on the perimeter of the site;\nb. Provisions for public safety;\nc. Pedestrian and vehicular site access points and construction activity zones;\nd. Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements; and\niii. Measures to ensure pedestrian safety near the site;\ne. Details of bulk earthworks to be carried out;\nf. The location of site storage areas and sheds;\ng. The equipment used to carry out works;\nh. The location of a garbage container with a tight-fitting lid;\ni. Dust, noise and vibration control measures;\nj. The location of temporary toilets;\nk. The protective measures for the preservation of trees on-site and in adjoining public areas\nincluding measures in accordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An applicable Development Control Plan;\niii. An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on site at all times while work is\nbeing carried out.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"17","code":null,"number":"17","title":"Car parking details","text":"Before the issue of the relevant construction certificate, written evidence prepared by a suitably\nqualified engineer must be obtained that demonstrates, to the certifier’s satisfaction, the plans for\nparking facilities comply with the relevant parts of AS 2890.1 Parking Facilities -Off-Street Carparking\nand Chapter B8 of council’s relevant development control plan (in force as at the date of\ndetermination of this consent).","stage":"before_cc","stage_basis":"heading","page":11},{"label":"18","code":null,"number":"18","title":"Retaining walls","text":"All retaining walls within 1m of a boundary and exceeding 600mm in height must be designed and\ncertified by a suitably qualified Structural Engineer.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to issue of a\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"19","code":null,"number":"19","title":"Equal access to the premises","text":"Before the issue of a construction certificate, plans which demonstrate that adequate access to the\npremises will be provided for persons with disabilities in accordance with the Commonwealth\nDisability (Access to Premises - Buildings) Standards 2010. These plans must be submitted to the\ncertifier.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"20","code":null,"number":"20","title":"Housing and Productivity Contribution","text":"A housing and productivity contribution is to be made, subject to:\na) Any exclusion of the application of Subdivision 4 of Division 7.1 of the Act to the\ndevelopment by a planning agreement; and\nb) Any exemption or reduction provided by the Environmental Planning and Assessment\n(Housing and Productivity Contribution) Order 2023 (the Order).\nIn this respect -\na) The housing and productivity contribution (HPC) set out in the table below, but as adjusted\nin accordance with this condition, is required to be made:\nHousing and Productivity Contribution Amount\nHousing and Productivity Contribution -\nLower Hunter Region\n$94,434.46\nb) The time by which the housing and productivity contribution must be made is before the\nissue of a Construction Certificate.\nc) The payment of the contributions must be made using the NSW Planning Portal.\nd) If an agreement is entered into as referred to in Clause 19 of the Order, the housing and\nproductivity contribution may be made wholly or partly as a non-monetary contribution.\nThe amount payable at the time of payment is the amount shown in the table above as the total\nhousing and productivity contribution, adjusted by multiplying it by the following fraction:\n𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉𝒉 𝑷𝑷𝑷𝑷𝑷𝑷 𝒏𝒏𝒏𝒏𝒏𝒏𝒏𝒏𝒉𝒉𝒏𝒏\n𝒄𝒄𝒄𝒄𝒏𝒏𝒉𝒉𝒉𝒉𝒏𝒏𝒉𝒉 𝑷𝑷𝑷𝑷𝑷𝑷 𝒏𝒏𝒏𝒏𝒏𝒏𝒏𝒏𝒉𝒉𝒏𝒏\nWhere -\nhighest PPI number is the highest PPI number for a quarter following the June quarter 2023 and up\nto and including the 2nd last quarter before the quarter in which the payment is made; and\nConsent PPI is the PPI number last used to adjust the base component amount, SBC amount or TPC\namount when consent was granted.\nJune quarter 2023 is the quarter commencing on and including 1 April 2023 and ending on and\nincluding 30 June 2023; and\nPPI is the Producer Price Index (Road and Bridge Construction (NSW)) published by the Australian\nBureau of Statistics).\nIf the amount adjusted in accordance with this condition is less than the amount at the time consent\nis granted, the higher amount must be paid instead.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"21","code":null,"number":"21","title":"Detailed Design in accordance with Acoustic Report","text":"Detailed design of the development is to be in accordance with the recommendations of Acoustic\nAssessment Report No. TN679-01F02, Version 4, prepared by Renzo Tonin and Associates dated 27\nFebruary 2024. Certification the design accords with the Acoustic Assessment Report No. TN679-\n01F02 by a suitably qualified acoustic engineer is to be provided to the Certifying Authority.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"22","code":null,"number":"22","title":"Retaining Walls","text":"Retaining walls proposed along the western boundary of the site must not exceed 1m (RL 5.2m) in\nheight from the finished ground level (RL 4.2m).\nAll retaining walls within 1m of a boundary and exceeding 600mm in height must be designed and\ncertified by a suitably qualified Structural Engineer. Details demonstrating compliance must be\nprovided to the Certifying Authority.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"23","code":null,"number":"23","title":"Public liability insurance","text":"The owner or contractor must take out a Public Liability Insurance Policy with a minimum cover of\n$20 million in relation to the occupation of, and works within, public property (i.e. kerbs, gutters,\nfootpaths, walkways, reserves, etc.) for the full duration of the proposed works.\nEvidence of this Policy must be provided to Council and the Certifying Authority.","stage":"before_work","stage_basis":"heading","page":13},{"label":"24","code":null,"number":"24","title":"Erosion and sediment controls in place","text":"Before any site work commences, the certifier must be satisfied the erosion and sediment controls in\nthe erosion and sediment control plan are in place. These controls must remain in place until any\nbare earth has been re-stabilized in accordance with 'Managing Urban Stormwater: Soils and\nConstruction’ prepared by Landcom (the Blue Book) (as amended from time to time).","stage":"before_work","stage_basis":"heading","page":14},{"label":"25","code":null,"number":"25","title":"All Weather Access","text":"A 3m wide all-weather vehicle access is to be provided from the kerb and gutter to the building\nunder construction for the delivery of materials and use by trades people.\nNo materials, waste or the like are to be stored on the all-weather access at any time.","stage":"before_work","stage_basis":"heading","page":14},{"label":"26","code":null,"number":"26","title":"Construction Certificate Required","text":"In accordance with the provisions of Section 6.7 of the Environmental Planning & Assessment Act\n1979 (EP&A Act 1979), construction or subdivision works approved by this consent must not\ncommence until the following has been satisfied:\na) A Construction Certificate has been issued by a Consent Authority;\nb) A Principal Certifying Authority (PCA) has been appointed by the person having benefit of the\ndevelopment consent in accordance with Section 6.5 of the EP&A Act 1979; and\nc) The PCA is notified in writing of the name and contractor license number of the\nowner/building intending to carry out the approved work.","stage":"before_work","stage_basis":"heading","page":14},{"label":"27","code":null,"number":"27","title":"Notice Commencement of Work","text":"Notice must be given to Council and the Principal Certifier, if not the Council, of the person’s\nintention to commence the erection of the building or undertake subdivision work at least two days\nprior to subdivision and/or building works commencing in accordance with Sections 6.6 (2) and 6.12\n(2) (c) of the Environmental Planning and Assessment Act 1979 and Section 59 of the Environmental\nPlanning and Assessment (Development Certification and Fire Safety) Regulation 2021. The notice\nmust include:\na) The name and address of the person;\nb) A description of the work to be carried out;\nc) The address of the land on which the work is to be carried out;\nd) The Registered numbers and date of issue of the development consent and construction\ncertificate;\ne) A statement signed by or on behalf of the principal certifier that all conditions of the consent\nthat must be satisfied before work commences have been satisfied; and\nf) The date on which the work is intended to commence.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_work","stage_basis":"heading","page":14},{"label":"28","code":null,"number":"28","title":"Notice of Principal Certifying Authority Appointment","text":"The Principal Certifier for this development must give notice must be given to the consent authority\nand Council, where the Council is not the consent authority, at least two days prior to subdivision\nand/or building works commencing in accordance with Section 6.6 (2) (a) of the Environmental\nPlanning and Assessment Act 1979 and Section 57 of the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021. The notice must include:\na) A description of the work to be carried out;\nb) The address of the land on which the work is to be carried out;\nc) The Registered number and date of issue of the relevant development consent;\nd) The name and address of the Principal Certifier and the person who appointed the principal\ncertifier;\ne) If the principal certifier is a registered certifier\ni) The certifier’s registration number, and\nii) A statement signed by the registered certifier to the effect that the certifier consents to\nbe appointed as principal certifier, and\niii) A telephone number on which the certifier may be contacted for business purposes.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_work","stage_basis":"heading","page":15},{"label":"29","code":null,"number":"29","title":"Damage report - Public Infrastructure","text":"Before any site work commences, the applicant is required to notify Council in writing of any existing\ndamage to public infrastructure (including landscaping) within the vicinity of the development, the\nabsence of such notification signifies that no damage exists","stage":"before_work","stage_basis":"heading","page":15},{"label":"30","code":null,"number":"30","title":"Rubbish Generated from the Development","text":"Where not already available, a waste containment facility is to be established on site. The facility is\nto be regularly emptied and maintained for the duration of works.\nNo rubbish must be stockpiled in a manner which facilitates the rubbish to be blown or washed off\nsite. The site must be cleared of all building refuse and spoil immediately upon completion of the\ndevelopment.","stage":"before_work","stage_basis":"heading","page":15},{"label":"31","code":null,"number":"31","title":"Signs on site","text":"A sign must be erected in a prominent position on any site on which building work or demolition\nwork is being carried out:\na) showing the name, address and telephone number of the principal certifier for the work, and\nb) showing the name of the principal contractor (if any) for any building work and a telephone\nnumber on which that person may be contacted outside working hours, and\nc) stating that unauthorised entry to the work site is prohibited.\nAny such sign is to be maintained while the building work or demolition work is being carried out,\nbut must be removed when the work has been completed.\nNote: This does not apply in relation to building work or demolition work that is carried out inside an\nexisting building that does not affect the external walls of the building.","stage":"before_work","stage_basis":"heading","page":15},{"label":"32","code":null,"number":"32","title":"Site is to be secured","text":"The site must be secured and fenced to the satisfaction of the Principal Certifying Authority. All\nhoarding, fencing, or awnings (associated with securing the site during construction is to be removed\nupon the completion of works.","stage":"before_work","stage_basis":"heading","page":16},{"label":"33","code":null,"number":"33","title":"Weed Management","text":"Weed removal and suppression must be undertaken using approved bush regeneration techniques\nunder the supervision of a suitably qualified and approved bush regenerator and in accordance with\nthe requirements for the NSW Biosecurity Act 2015, associated Regulations and NSW Weed Control\nHandbook. The site is to be inspected by a representative of Council’s Invasive Species team one\nweek prior to works commencing.","stage":"before_work","stage_basis":"heading","page":16},{"label":"34","code":null,"number":"34","title":"Construction Management Plan implementation -","text":"All construction management procedures and systems identified in the approved Construction Site\nManagement Plan must be introduced and maintained during construction of the development.","stage":"during_work","stage_basis":"heading","page":16},{"label":"35","code":null,"number":"35","title":"Discovery of relics and Aboriginal objects","text":"While site works is being carried out, if a person reasonably suspects a relic or Aboriginal object is\ndiscovered:\na. The work in the area of the discovery must cease immediately;\nb. The following must be notified -\ni. For a relic - the Heritage Council; or\nii. For an Aboriginal object - the person who is the authority for the protection of Aboriginal\nobjects and Aboriginal places in New South Wales under the National Parks and Wildlife\nAct 1974, Section 85.\nSite works may recommence at a time conformed in writing by:\na. For a relic - the Heritage Council; or\nb. For an Aboriginal object - the person who is the authority for the protection of Aboriginal\nobjects and Aboriginal places in New South Wales under the National Parks and Wildlife Act\n1974, section 85","stage":"during_work","stage_basis":"heading","page":16},{"label":"36","code":null,"number":"36","title":"PFAS Contamination Management","text":"During earthworks and construction works the Northrop (2024) PFAS Management Plan for Astra\nAerolab Stages 2A, 2C, 4 & 5 must be implemented. The following is also required to be complied\nwith:\n1. Where the potential for Per- and Poly-Fluoroalkyl Substances (PFAS) contamination exists in\nsoil, groundwater or surface water at the development site, the applicant must identify\nwhether any construction activities could disturb or interact with any PFAS contaminated\nsoil, groundwater or surface water.\n2. If construction activities could disturb or interact with any PFAS contaminated soil,\ngroundwater or surface water, the applicant must:\na. prevent, or limit as far as possible, offsite migration of PFAS contamination;\nb. prevent, or limit as far as possible, contact and exposure to PFAS;\nc. manage potentially PFAS impacted groundwater that may accumulate in any\nfootings or excavations to ensure this does not run-off the site;\nd. manage any PFAS-impacted soils, by controlling erosion and covering stockpiles\nof PFAS impacted soils to protect from rainfall egress and runoff; and e. ensure\nthat any PFAS contaminated material transported from the site to a site that is\nlawfully able to receive it.\n3. Where PFAS contaminated material is to be removed from the site, the applicant must\nsample the soil for PFAS and classify the soil in accordance with the EPA’s Addendum to the\nWaste Classification Guidelines (2014) - Part 1: classifying waste to identify lawful\nmanagement and disposal options.","stage":"during_work","stage_basis":"heading","page":17},{"label":"37","code":null,"number":"37","title":"Construction Noise","text":"While building work is being carried out, the applicant must ensure that any noise generated from\nthe site is controlled in accordance with Acoustic Assessment (reference: TN679-01F02 Acoustic\nAssessment for DA (r4)).","stage":"during_work","stage_basis":"heading","page":17},{"label":"38","code":null,"number":"38","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved removal,\nrelocation or reconstruction of infrastructure (including ramps, footpaths, kerb and gutter, light\npoles, kerb inlet pits, service provider pits, street trees or any other infrastructure in the street\nfootpath area) must be paid as directed by the consent authority.","stage":"during_work","stage_basis":"heading","page":17},{"label":"39","code":null,"number":"39","title":"Waste management","text":"While site work is being carried out:\n1. all waste management must be undertaken in accordance with the waste management plan;\nand\n2. upon disposal of waste, records of the disposal must be compiled and provided to the\ncertifying authority, detailing the following:\na. The contact details of the person(s) who removed the waste;\nb. The waste carrier vehicle registration;\nc. The date and time of waste collection;\nd. A description of the waste (type of waste and estimated quantity) and whether the\nwaste is to be reused, recycled or go to landfill;\ne. The address of the disposal location(s) where the waste was taken;\nf. The corresponding tip docket/receipt from the site(s) to which the waste is\ntransferred, noting date and time of delivery, description (type and quantity) of\nwaste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or Exemption,\nrecords in relation to that Order or Exemption must be maintained and provided to the principal\ncertifier and Council.","stage":"during_work","stage_basis":"heading","page":17},{"label":"40","code":null,"number":"40","title":"Hours of work","text":"Site work must only be carried out between the following times -\n7:00am to 5:00pm on Monday to Saturday\nSite work is not to be carried out outside of these times except where there is an emergency, or\nfor urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":18},{"label":"41","code":null,"number":"41","title":"Weed management","text":"All machinery that has operated in affected areas shall be cleaned thoroughly prior to leaving the\nsite. A wash down area shall be established, and monitored for priority weeds as defined by the NSW\nBiosecurity Act 2015. Cleaning must include the removal of all mud and plant matter, followed by\nwashing with high pressure water. An area for storage of contaminated spoil that is separate from\nclean material shall be provided during construction.","stage":"during_work","stage_basis":"heading","page":18},{"label":"42","code":null,"number":"42","title":"Unexpected Finds Contingency (General)","text":"Should any suspect materials (identified by unusual staining, odour, discolouration or inclusions such\nas building rubble, asbestos, ash material, etc.) be encountered during any stage of works (including\nearthworks, site preparation or construction works, etc.), such works must cease immediately until a\nqualified environmental specialist has be contacted and conducted a thorough assessment.\nIn the event that contamination is identified as a result of this assessment and if remediation is\nrequired, all works must cease in the vicinity of the contamination and Council must be notified\nimmediately.\nWhere remediation work is required, the applicant will be required to obtain consent for the\nremediation works.","stage":"during_work","stage_basis":"heading","page":18},{"label":"43","code":null,"number":"43","title":"Excavations and Backfilling","text":"All excavations and backfilling associated with this development consent must be executed safely,\nand be properly guarded and protected to prevent them from being dangerous to life or property,\nand in accordance with the design of a suitably qualified Structural Engineer.\nIf an excavation extends below the level of the base of the footings of a building on an adjoining\nallotment, the person causing the excavation must:\na) preserve and protect the building from damage; and\nb) if necessary, underpin and support the building in an approved manner; and\nc) give at least seven days’ notice to the adjoining owners before excavating, or of the intention\nto excavate.\nThe principal contractor, owner builder or any person who needs to excavate and undertake building\nwork, must contact “Dial Before You Dig” prior to works commencing, and allow a reasonable period\nof time for the utilities to provide locations of their underground assets.\nThis condition does not apply if the person having the benefit of the development consent owns the\nadjoining land or the owner of the adjoining land has given consent in writing to that condition not\napplying.","stage":"during_work","stage_basis":"heading","page":19},{"label":"44","code":null,"number":"44","title":"Offensive noise, dust, odour, and vibration","text":"Work must not give rise to offensive noise, odour, or vibration as defined in the Protection of the\nEnvironment Operations Act 1997 when measured at the nearest property boundary.","stage":"during_work","stage_basis":"heading","page":19},{"label":"45","code":null,"number":"45","title":"Toilet Facilities","text":"Temporary toilet(s) must be provided and maintained on site from the time of commencement of\nbuilding work to completion. The number of toilets provided must be one toilet per 20 persons or\npart thereof employed on the site at any one time.\nThe temporary toilet is to be either connected to the sewerage system or an approved septic tank or\notherwise may be a chemical toilet supplied by a licensed contractor.","stage":"during_work","stage_basis":"heading","page":19},{"label":"46","code":null,"number":"46","title":"Compliance with the Building Code of Australia","text":"Building work must be carried out in accordance with the requirements of the Building Code of\nAustralia.","stage":"during_work","stage_basis":"heading","page":19},{"label":"47","code":null,"number":"47","title":"Cut and fill (if applicable)","text":"While building work is being carried out, the principal certifier must be satisfied all soil removed from\nor imported to the site is managed in accordance with the following requirements:\n(a) All excavated material removed from the site must be classified in accordance with the EPA’s\nWaste Classification Guidelines before it is disposed of at an approved waste management\nfacility and the classification and the volume of material removed must be reported to the\nprincipal certifier.\n(b) All fill material imported to the site must be Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997 or a material identified\nas being subject to a resource recovery exemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":20},{"label":"48","code":null,"number":"48","title":"Building Height","text":"A survey report prepared by a Registered Surveyor confirming that the building height complies with\nthe approved plans (Top of Roof Parapet 19.23m/RL 23.73) must be provided to the Principal\nCertifying Authority prior to the development proceeding beyond frame stage.","stage":"during_work","stage_basis":"heading","page":20},{"label":"49","code":null,"number":"49","title":"Flood Emergency Response Plan","text":"A Flood Emergency Response Plan (FERP) for the proposed development must be provided to the\nPrincipal Certifying Authority before the issue of an Occupation Certificate. The FERP must include\nthe following as a minimum:\na) A map of the proposed evacuation route to a suitable location above the Probable Maximum\nFlood (PMF) that provides adequate shelter from the storm, including the route direction\nand description and identification of the depth of floodwater along the evacuation route in\nthe 1% Annual Exceedance Probability flood and PMF events;\nb) Specific trigger heights linked to the nearest river and tidal gauges used for flood warnings\nand the specific evacuation route cut-off times linked to the gauge height;\nc) Description of the specific flood inundation at the site and the relevant surrounding area,\nincluding flood depths, direction of flow, velocities, hazard and specific relevant\nvulnerabilities;\nd) Consideration of and strategies for, the needs of the elderly, disabled and vulnerable who\nmay be on site;\ne) A realistic time period for evacuation preparations linked to the trigger heights and\nevacuation route cut-off times, which includes:\no Locating important papers, valuables etc., that will be evacuated\no Locating and stacking possessions that are to be left behind, well above the\npredicted flood level\no Dealing with all utilities such as electricity, gas, water, fuel, toilets, showers,\nwastewater system (including removal fuses) and moving pumps and machinery\nabove the predicted flood level\no Time to gather, identify and load animals (pets, livestock and other animals),\nincluding the possible need for additional assistance in handling your animals in an\nemergency.\nf) Determining the vehicular needs of the site to appropriately respond to the flood risk;\ng) A strategy for a night time flood emergency; and\nh) A strategy for effective flood risk management when the electricity, internet,\ntelecommunications etc., are unavailable.\nNote: Digital elevation data is available from Geosciences Australia, current flood studies are\navailable on Council's website and river gauge/ tidal gauge data is available from the Bureau of\nMeteorology website.","stage":"before_oc","stage_basis":"heading","page":20},{"label":"50","code":null,"number":"50","title":"Occupation Certificate Required","text":"An Occupation Certificate must be obtained prior to any use or occupation of the development.\nThe Principal Certifying Authority must be satisfied that the development has been constructed in\naccordance with approved plans, specifications and conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"51","code":null,"number":"51","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":21},{"label":"52","code":null,"number":"52","title":"Completion of landscape and tree works","text":"Before the issue of an occupation certificate, the principal certifier must be satisfied that all\nlandscape and tree-works, including pruning in accordance with AS 4373-2007 Pruning of amenity\ntrees and the removal of all noxious weed species, have been completed in accordance with the\napproved plans and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"53","code":null,"number":"53","title":"Completion of Roads Act Approval works","text":"Before the issue of an occupation certificate, all approved road, footpath and/or drainage works,\nincluding vehicle crossings, have been completed in the road reserve in accordance with the Roads\nAct Approval to the satisfaction of the Council as the Roads Authority.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"54","code":null,"number":"54","title":"Removal of waste upon completion","text":"Before the issue of an occupation certificate, the principal certifier must ensure all refuse, spoil and\nmaterial unsuitable for use on-site is removed from the site and disposed of in accordance with the\napproved waste management plan. Written evidence of the removal must be supplied to the\nsatisfaction of the principal certifier.\nBefore the issue of a partial occupation certificate, the applicant must ensure the temporary storage\nof any waste is carried out in accordance with the approved waste management plan to the principal\ncertifier’s satisfaction.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"55","code":null,"number":"55","title":"Stormwater/drainage works","text":"All stormwater and drainage works required to be undertaken in accordance with this consent must\nbe completed before the issue of an occupation certificate.\nThe certification/verification must be provided to the satisfaction of the Principal Certifying\nAuthority.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"56","code":null,"number":"56","title":"Car parking requirements","text":"Before the issue of an occupation certificate, a minimum of 183 car parking spaces including 8\naccessible car parking spaces and 18 car parking spaces with capacity to provide electric charging\nfacilities are to be provided in accordance with AS2890 and the approved plans.\nParking must be permanently marked on the pavement surface.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"57","code":null,"number":"57","title":"Loading/Unloading Facilities","text":"Before the issue of an occupation certificate, loading / unloading facilities must be constructed in\naccordance with the approved plans. The extent of the loading bay must be permanently marked on\nthe pavement surface.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"58","code":null,"number":"58","title":"Services","text":"Evidence is to be provided to Council demonstrating that the following reticulated services are\navailable to each lot:\na) Electricity;\nb) Water;\nc) Sewer; and\nd) Gas (where available).\nShould any of the above reticulated services not be available to the development site, a detailed\nstatement is to be provided explaining why connection of the relevant service is not possible or\npractical.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"59","code":null,"number":"59","title":"Water authority certification","text":"Before the issue of an occupation certificate, a certificate of compliance must be obtained in relation\nto the proposed use from Hunter Water Corporation.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"60","code":null,"number":"60","title":"Construction to be in accordance with Acoustic Report","text":"Certification is to be submitted to the Principal Certifying Authority to certify that the construction of\nthe development complies with the recommendations of the Acoustic Assessment Report No.\nTN679-01F02, prepared by Renzo Tonin and Associates dated 27 February 2024.\nBushfire safety","stage":"before_oc","stage_basis":"heading","page":23},{"label":"61","code":null,"number":"61","title":"","text":"The site is located within a bushfire prone area and must comply with NSW Rural Fire Service\ndocument \"Planning for Bushfire Protection 2019\" (PBP2019). In this regard the following is required:\n• The site (approved lots 200 and 201) must be managed as an ‘Inner Protection Area’ as\noutlined within PBP2019.\n• The development is to be constructed in accordance with the access provisions of Chapter 8\nof PBP 2019;\n• The development is to be connected to a reliable water supply network and suitable fire\nhydrants are to be clearly marked and provided for the purposes of bushfire protection. Fire\nhydrant spacing, fixing and pressure shall comply with AS2419.1 - 2005 and PBP 2019 (Table\n7.4a);\n• The provision of electricity must comply the following in accordance with Table 7.4a of PBP\n2019;\n• Any hazardous materials must be stored away from the bushfire hazard wherever possible.\n• An Emergency Evacuation Plan is to be prepared.\nBefore the issue of an occupation certificate, details demonstrating compliance must be provided to\nthe Certifying Authority by an NSW suitably qualified BPAD Bushfire Consultant.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"62","code":null,"number":"62","title":"Outdoor Lighting","text":"Prior to the issue of an occupation certificate, details demonstrating that all lighting complies with AS\n1158 ‘Lighting for Roads and Public Spaces’ and AS 4282 ‘Control of Obtrusive Effects of Outdoor\nLighting’ and the lighting controls detailed in the Civil Aviation Safety Authority (CASA) Manual of\nStandards (MOS-139) Aerodromes must be provided to the Certifying Authority.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"63","code":null,"number":"63","title":"Completion of landscape and tree works","text":"Before the issue of an occupation certificate, the principal certifier must be satisfied that all\nlandscape and tree-works, including pruning in accordance with AS 4373-2007 Pruning of amenity\ntrees and the removal of all noxious weed species, have been completed in accordance with the\napproved plans and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"64","code":null,"number":"64","title":"Driveways to be maintained","text":"All access crossings and driveways must be maintained in good order for the life of the development","stage":"ongoing","stage_basis":"heading","page":24},{"label":"65","code":null,"number":"65","title":"Impact to adjoining properties","text":"The development must not undertake activities which may restrict, obstruct or inconvenience the\nuse of the land by other users, outside of the approved development location.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"66","code":null,"number":"66","title":"Industrial Uses","text":"All industrial activity in connection with the use of the subject property is to be wholly confined\nwithin the building.\nAny approved office space is to be used solely in conjunction with the industrial use of the premises\nto which it is attached. The separate use or occupation of the approved office space is not permitted\nby this consent.\nThe use of the factory unit for retail activities is prohibited.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"67","code":null,"number":"67","title":"Loading to occur on site","text":"All loading and unloading operations are to be carried out wholly within the building/site and in\naccordance with the approved plans.\nThe loading dock (if provided) must be used for loading and unloading operations in connection with\nthe approved use.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"68","code":null,"number":"68","title":"Maintenance of Landscaping","text":"Landscaping must be maintained in accordance with the approved landscape plan and conditions of\nthis development consent. All landscape areas must be kept free of parked vehicles, stored goods,\ngarbage or waste material at all times.\nIf any of the vegetation dies or is removed, it is to be replaced with vegetation of the same species\nand similar maturity as the vegetation which has died or was removed.","stage":"ongoing","stage_basis":"heading","page":24},{"label":"69","code":null,"number":"69","title":"Manoeuvring of Vehicles","text":"All vehicles must enter and exit the site in a forward direction.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"70","code":null,"number":"70","title":"Offensive Noise","text":"The use and occupation of the premises including all plant and equipment must not give rise to any\noffensive noise within the meaning of the Protection of the Environment Operation Act 1997 and\nmust comply with the NSW Noise Policy for Industry 2017 (as amended).","stage":"ongoing","stage_basis":"heading","page":25},{"label":"71","code":null,"number":"71","title":"Parking areas to be kept clear","text":"At all times, the loading, car parking spaces, driveways and footpaths must be kept clear of goods\nand must not be used for storage purposes.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"72","code":null,"number":"72","title":"Storage of goods","text":"The storage of goods and materials must be confined within the building. At no time must goods,\nmaterials or advertising signs be displayed or placed within the designated car parking spaces,\nlandscaped areas or road reserve.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"73","code":null,"number":"73","title":"Amenity","text":"The business must be conducted, and customers controlled at all times so that no interference\noccurs to the amenity of the area, the footpath, adjoining occupations and residential or business\npremises.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"74","code":null,"number":"74","title":"Maintenance of stormwater","text":"The stormwater system, including any water quality or quantity components, shall be maintained in\nperpetuity for the life of the development.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"75","code":null,"number":"75","title":"Waste Management","text":"Operational waste management must be managed in accordance with the approved operational\nwaste management plan referenced in Condition 1.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"76","code":null,"number":"76","title":"Waste Storage","text":"As the subject site is located in an area mapped by the Department of Defence as “Birdstrike Group\nA”, organic waste and/or the storage of bins associated with any future development must be\ncovered and/or enclosed and limited on-site.","stage":"ongoing","stage_basis":"heading","page":26},{"label":"77","code":null,"number":"77","title":"Hazardous material storage","text":"Dangerous and hazardous goods must be stored in accordance with SafeWork NSW requirements,\ndependent on the quantities stored. Any flammable or combustible liquids must be stored in\naccordance with AS 1940 'The Storage and Handling of Flammable and Combustible Liquids'.\nHazardous and/or industrial waste arising from the use must be removed and/or transported in\naccordance with the requirements of the Environmental Protection Agency and the SafeWork NSW.","stage":"ongoing","stage_basis":"heading","page":26},{"label":"78","code":null,"number":"78","title":"Hours of operation","text":"The property is only to be open for business and used for the purpose approved within the following\nhours:\nDay Hours of Operation\nMonday - Sunday 7:00am - 6:00pm\nOther internal operations such as cleaning, preparation, and office administration may be\nundertaken outside of the above hours provided no disturbance to the amenity of the\nneighbourhood occurs.\nCondition reason - To ensure the development operates within the approved operating hours.","stage":"ongoing","stage_basis":"heading","page":26}]});
